#toolset {
	display: none;
}


body {
	background-color: #fff;
	color: #000;
}

a:active {
	opacity: 0.7;
}

.page a.active {
	color: #f17108;
}

i,
em {
	font-style: italic;
}

b,
strong {
	font-weight: bolder;
}

sub,
sup {
	position: relative;
	vertical-align: baseline;
}

sub {
	top: 0.3em;
}

sup {
	top: -0.4em;
}

s {
	text-decoration: line-through;
}

img {
	border: 0;
	padding: 0;
}

ul,
ol {
	margin: 0;
	padding: 0 0 0 2.5em;
}

blockquote {
	margin: 0;
	padding: 0 0 0 1em;
}

hr {
	background: rgba(0, 0, 0, 0.6);
	border: 0;
	height: 2px;
	display: block;
    margin-top: 1.0rem;
    margin-bottom: 1.0rem;
}

.content img {
	float: none;
	margin-bottom: 0;
    vertical-align: bottom;
}

[image-gallery="slideshow"] {
    margin-bottom: 2rem;
}

.gallery_image_caption {
    margin-top: 1.5rem;
    margin-bottom: 0.5rem;
    font-size: 1.1rem;
	font-weight: 400;
	color: rgba(0, 0, 0, 0.4);
	font-family: Diatype, Icons;
	font-style: normal;
	line-height: 1.2;	
}

/**
 * Loading Animation
 */





.loading[data-loading] {
	position: fixed;
	bottom: 8px; 
    left: 9px;
}

/**
 * Editor styles
 */

[data-predefined-style="true"] bodycopy {
	font-size: 1.0rem;
	font-weight: 700;
